output_text:
[
  {
    "id": "borrow_entrance_cart",
    "text": "A shopper is obliged to pick up the cart stationed at the entrance before doing the trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "return_cart_to_service",
    "text": "Any cart picked up by the shopper must eventually be returned to the customer-service return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "customer_service_bay": "at(0,1)",
        "pushing_cart": "hasCart",
        "cart_parked_at_service": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "pushing_cart"
        },
        "return_cart_to_service": {
          "pre": {
            "and": [
              "customer_service_bay",
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_service"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_service"
    }
  },
  {
    "id": "no_cart_abandonment",
    "text": "Leaving a cart is prohibited except at the customer-service return bay.",
    "abstraction": {
      "state_properties": {
        "designated_cart_return_bay": "at(0,1)"
      },
      "events": {
        "put_down_cart": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "put_down_cart",
          {
            "not": "designated_cart_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "exit_without_cart",
    "text": "A shopper is prohibited from leaving the store while still pushing the cart.",
    "abstraction": {
      "state_properties": {
        "exit_cell": "at(9,5)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "exit_store": {
          "pre": {
            "and": [
              "exit_cell",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_store",
          "pushing_cart"
        ]
      }
    }
  },
  {
    "id": "items_must_go_in_cart",
    "text": "Shelf items may be picked up only while the shopper has a cart, rather than being collected without one.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "shelf_item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "shelf_item_pickup",
          "without_cart"
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Carrying merchandise by hand is prohibited; items should be transported in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "pushing_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "upper_central_cart_only",
    "text": "The upper central shopping aisles may be used by cart-pushing shoppers but are prohibited for pedestrians without carts.",
    "abstraction": {
      "state_properties": {
        "upper_central_area": {
          "or": [
            "at(2,2)",
            "at(2,3)",
            "at(3,2)",
            "at(3,3)",
            "at(4,2)",
            "at(4,3)",
            "at(5,2)",
            "at(5,3)",
            "at(6,2)",
            "at(6,3)",
            "at(7,2)",
            "at(7,3)",
            "at(8,2)",
            "at(8,3)"
          ]
        },
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "upper_central_area",
          "without_cart"
        ]
      }
    }
  },
  {
    "id": "bottom_aisle_north_only_with_cart",
    "text": "Turning north out of the bottom aisle into the shopping area is allowed only for shoppers who are pushing a cart.",
    "abstraction": {
      "state_properties": {
        "bottom_aisle": {
          "or": [
            "at(0,5)",
            "at(1,5)",
            "at(2,5)",
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "turn_north_from_bottom": {
          "pre": {
            "and": [
              "bottom_aisle",
              "N"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "turn_north_from_bottom",
          "without_cart"
        ]
      }
    }
  }
]
